def scramble_word(word):
    """Scramble a given word using a simple substitution cipher."""
    scrambled_word = ""
    for char in word:
        if char.isalpha():
            scrambled_word += chr((ord(char) - ord('a') + 3) % 26 + ord('a'))
        else:
            scrambled_word += char
    return scrambled_word

def unscramble_word(scrambled_word):
    """Unscramble a given scrambled word."""
    unscrambled_word = ""
    for char in scrambled_word:
        if char.isalpha():
            unscrambled_word += chr((ord(char) - ord('a') - 3) % 26 + ord('a'))
        else:
            unscrambled_word += char
    return unscrambled_word

def main():
    print("Welcome to the Word Scrambler!")
    while True:
        user_input = input("Enter a word to scramble: ").lower()
        if user_input == "quit":
            break

        scrambled_word = scramble_word(user_input)
        print(f"Scrambled word: {scrambled_word}")

        user_answer = input("Enter the unscrambled word: ").lower()
        if unscramble_word(user_answer) == user_input:
            print("Correct!")
        else:
            print("Incorrect. The unscrambled word was:", user_input)

    print("Goodbye!")

if __name__ == "__main__":
    main()
```

This program defines three functions: `scramble_word()` to scramble a given word, `unscramble_word()` to unscramble a given scrambled word, and `main()` to run the entire program. The `main()` function prompts the user for input, scrambles the word, and then asks the user to unscramble it. The unscrambled word is compared to the original input to determine if the user's answer is correct.
